CREATE DATABASE IF NOT EXISTS wisio CHARACTER SET utf8mb4 COLLATE utf8mb4_turkish_ci;
USE wisio;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS audit_logs,notifications,reports,files,messages,knowledge_card_versions,knowledge_cards,answer_verifications,answers,question_targets,questions,user_expertise,topics,announcements,community_members,communities,users;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,username VARCHAR(30) NOT NULL UNIQUE,email VARCHAR(190) NOT NULL UNIQUE,phone VARCHAR(30),password_hash VARCHAR(255) NOT NULL,avatar VARCHAR(255),status ENUM('active','blocked') DEFAULT 'active',trust_label VARCHAR(40) DEFAULT 'Yeni',trust_score DECIMAL(5,2) DEFAULT 50,xp INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE communities(id INT AUTO_INCREMENT PRIMARY KEY,owner_id INT NOT NULL,name VARCHAR(150) NOT NULL UNIQUE,type VARCHAR(80) NOT NULL,description TEXT,visibility ENUM('open','approved','private','corporate') DEFAULT 'approved',join_method VARCHAR(40) DEFAULT 'approval',join_password_hash VARCHAR(255) NULL,status ENUM('active','archived') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(owner_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE community_members(community_id INT NOT NULL,user_id INT NOT NULL,role ENUM('admin','moderator','knowledge_manager','member') DEFAULT 'member',status ENUM('pending','active','muted','banned') DEFAULT 'active',joined_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(community_id,user_id),FOREIGN KEY(community_id) REFERENCES communities(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE announcements(id INT AUTO_INCREMENT PRIMARY KEY,community_id INT NOT NULL,author_id INT NOT NULL,title VARCHAR(180) NOT NULL,content TEXT NOT NULL,is_pinned TINYINT(1) DEFAULT 0,status ENUM('published','archived') DEFAULT 'published',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(community_id) REFERENCES communities(id) ON DELETE CASCADE,FOREIGN KEY(author_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE topics(id INT AUTO_INCREMENT PRIMARY KEY,parent_id INT NULL,name VARCHAR(120) NOT NULL,description TEXT,sensitivity_level ENUM('public','community','role','private','restricted') DEFAULT 'community',FOREIGN KEY(parent_id) REFERENCES topics(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE user_expertise(user_id INT NOT NULL,topic_id INT NOT NULL,source ENUM('self','answers','community','admin','document') DEFAULT 'self',confidence_score DECIMAL(5,2) DEFAULT 50,verification_status ENUM('pending','verified','rejected') DEFAULT 'pending',visibility ENUM('community','private') DEFAULT 'community',availability ENUM('available','busy','away') DEFAULT 'available',PRIMARY KEY(user_id,topic_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(topic_id) REFERENCES topics(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE questions(id INT AUTO_INCREMENT PRIMARY KEY,community_id INT NOT NULL,asker_id INT NOT NULL,title VARCHAR(255) NOT NULL,description TEXT,topic_id INT NULL,visibility ENUM('public','community','role','private') DEFAULT 'community',anonymity TINYINT(1) DEFAULT 0,status ENUM('open','answered','closed','reported') DEFAULT 'open',urgency ENUM('low','normal','high') DEFAULT 'normal',expected_answer_type VARCHAR(30) DEFAULT 'any',target_count TINYINT UNSIGNED DEFAULT 3,allow_public_fallback TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(community_id) REFERENCES communities(id) ON DELETE CASCADE,FOREIGN KEY(asker_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(topic_id) REFERENCES topics(id) ON DELETE SET NULL,FULLTEXT KEY ft_question(title,description)) ENGINE=InnoDB;
CREATE TABLE question_targets(question_id INT NOT NULL,user_id INT NOT NULL,match_score DECIMAL(5,2) DEFAULT 0,notification_status VARCHAR(30) DEFAULT 'pending',response_status VARCHAR(30) DEFAULT 'pending',PRIMARY KEY(question_id,user_id),FOREIGN KEY(question_id) REFERENCES questions(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE answers(id INT AUTO_INCREMENT PRIMARY KEY,question_id INT NOT NULL,user_id INT NOT NULL,content TEXT NOT NULL,answer_type VARCHAR(30) DEFAULT 'text',status ENUM('published','hidden','reported') DEFAULT 'published',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(question_id) REFERENCES questions(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE answer_verifications(answer_id INT NOT NULL,verifier_id INT NOT NULL,verification_type ENUM('helpful','current','partial','outdated','wrong') DEFAULT 'helpful',comment TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(answer_id,verifier_id,verification_type),FOREIGN KEY(answer_id) REFERENCES answers(id) ON DELETE CASCADE,FOREIGN KEY(verifier_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE knowledge_cards(id INT AUTO_INCREMENT PRIMARY KEY,community_id INT NOT NULL,source_question_id INT NULL,title VARCHAR(255) NOT NULL,summary VARCHAR(500),content TEXT,topic_id INT NULL,visibility ENUM('public','community','role','private') DEFAULT 'community',owner_id INT NOT NULL,valid_until DATE,status ENUM('active','outdated','archived') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(community_id) REFERENCES communities(id) ON DELETE CASCADE,FOREIGN KEY(source_question_id) REFERENCES questions(id) ON DELETE SET NULL,FOREIGN KEY(topic_id) REFERENCES topics(id) ON DELETE SET NULL,FOREIGN KEY(owner_id) REFERENCES users(id) ON DELETE CASCADE,FULLTEXT KEY ft_card(title,summary,content)) ENGINE=InnoDB;
CREATE TABLE knowledge_card_versions(id INT AUTO_INCREMENT PRIMARY KEY,card_id INT NOT NULL,version_number INT NOT NULL,content TEXT,editor_id INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(card_id) REFERENCES knowledge_cards(id) ON DELETE CASCADE,FOREIGN KEY(editor_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE messages(id INT AUTO_INCREMENT PRIMARY KEY,question_id INT NOT NULL,sender_id INT NOT NULL,receiver_id INT NOT NULL,content TEXT NOT NULL,moderation_status VARCHAR(30) DEFAULT 'clean',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(question_id) REFERENCES questions(id) ON DELETE CASCADE,FOREIGN KEY(sender_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(receiver_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE files(id INT AUTO_INCREMENT PRIMARY KEY,uploader_id INT NOT NULL,community_id INT NOT NULL,entity_type VARCHAR(40),entity_id INT,file_path VARCHAR(255),visibility VARCHAR(30),security_status VARCHAR(30) DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE reports(id INT AUTO_INCREMENT PRIMARY KEY,reporter_id INT NOT NULL,target_type VARCHAR(40),target_id INT,reason TEXT,status VARCHAR(30) DEFAULT 'open',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE notifications(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,type VARCHAR(60),content TEXT,status VARCHAR(30) DEFAULT 'unread',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE audit_logs(id BIGINT AUTO_INCREMENT PRIMARY KEY,actor_id INT NULL,action VARCHAR(100),entity_type VARCHAR(40),entity_id INT,metadata JSON,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
