INSERT INTO questions(community_id,asker_id,title,description,topic_id,visibility,anonymity,status) VALUES (1,2,'Erasmus hibesi geç yatarsa hangi birimle görüşülüyor?','Geçen yıl başvuran ve benzer durum yaşayan birinin deneyimini arıyorum.',1,'community',0,'answered'),(2,4,'Eski satış raporundaki para birimi hatasını kim daha önce çözdü?','Raporlama ekranında TL yerine EUR görünüyor.',5,'community',0,'answered'),(3,1,'Apartmanın ana su vanası nerede?','Acil olmayan bakım için konumu öğrenmek istiyorum.',3,'community',0,'answered'),(1,4,'Staj evrakları hangi sırayla teslim ediliyor?','İlk kez başvuru yapacağım.',4,'community',0,'open');
