INSERT INTO answers(question_id,user_id,content) VALUES (1,1,'Önce bölüm Erasmus koordinatörüne e-posta gönderin. Çözülmezse Uluslararası İlişkiler Ofisinin hibe birimiyle görüşün. Benim ödemem geçen yıl üç hafta gecikmişti.'),(2,2,'Rapor ayarlarında para birimi alanı kullanıcı profilinden miras alıyor. Profilde varsayılan para birimini TL yapıp rapor önbelleğini temizleyin.'),(3,3,'Ana vana bodrum kattaki sayaç odasında, girişin sağ tarafındaki kırmızı kol üzerindedir.');
