INSERT INTO knowledge_cards(community_id,source_question_id,title,summary,content,topic_id,visibility,owner_id,valid_until,status) VALUES (1,1,'Erasmus hibesi gecikirse izlenecek yol','Önce bölüm koordinatörü, ardından Uluslararası İlişkiler Ofisi hibe birimiyle görüşülür.','Öğrenci portalından ödeme durumunu kontrol edin. Bölüm Erasmus koordinatörüne yazın. Çözülmezse Uluslararası İlişkiler Ofisinin hibe birimine başvurun.',1,'community',1,DATE_ADD(CURDATE(),INTERVAL 6 MONTH),'active'),(3,3,'Apartman ana su vanasının konumu','Bodrum kattaki sayaç odasında, girişin sağ tarafındadır.','Sayaç odasına bodrum kattan girilir. Ana vana sağ taraftaki kırmızı kollu vanadır.',3,'community',3,DATE_ADD(CURDATE(),INTERVAL 1 YEAR),'active');

INSERT INTO announcements(community_id,author_id,title,content,is_pinned) VALUES (1,1,'Wisio topluluğuna hoş geldiniz','Sorularınızı net yazın ve kişisel bilgi paylaşmayın. Doğrulanmış cevaplar bilgi kartına dönüştürülecektir.',1),(2,2,'Haftalık bilgi paylaşımı','Eski projelerle ilgili bildiğiniz konuları profilinize eklemeyi unutmayın.',0);
